"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.4\",\n    \"@fugood/whisper.node\": \"1.1.3\",\n    \"immer\": \"^11.2.9\",\n    \"zod\": \"^4.4.3\",\n    \"zustand\": \"~5.0.16\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-credentials\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.4\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@thesvg/react\": \"^4.0.4\",\n    \"@types/node\": \"^22.20.1\",\n    \"@types/react\": \"~18.3.31\",\n    \"lightningcss\": \"^1.33.0\",\n    \"react\": \"^18.3.1\",\n    \"tsdown\": \"^0.23.4\",\n    \"typescript\": \"7.0.2\",\n    \"vitest\": \"^5.1.0\"\n  }\n}\n"
