    {
      "path": "src/client/voice-flow.ts",
      "content": "import type { EarsSettings } from '../config.js'\nimport { isEarsErrorCode } from '../errors.js'\nimport { joinSpacedSegments } from '../text-join.js'\nimport type { EarsRemote } from '../remote.js'\nimport { classifyVoiceFailure, failureMessage, remoteFailureDetail, remoteFailureParams } from './voice-error.js'\nimport type { VoiceStateDetailParams } from './voice-session.js'\n\nexport type VoiceInputState = 'idle' | 'starting' | 'recording' | 'transcribing' | 'polishing' | 'error' | 'polish-error' | 'upstream-error'\n\nexport interface DraftActions {\n  setDraft(text: string): void\n}\n\nexport interface CommitTranscriptOptions {\n  transcript: string\n  baseDraft: string\n  expectedDraft?: string\n  requireUnchanged: boolean\n  transcriptAlreadyApplied?: boolean\n  settings: EarsSettings\n  remote: EarsRemote\n  setState: (state: VoiceInputState, detail?: string, detailCode?: string, detailParams?: VoiceStateDetailParams) => void\n  latestDraftRef: { current: string }\n  actionsRef: { current: DraftActions }\n  polishAbortRef: { current: AbortController | null }\n  isCurrent?: () => boolean\n}\n\nexport function commitTranscript(options: CommitTranscriptOptions): void {\n  const transcript = options.transcript.trim()\n  if (transcript === '') {\n    options.setState('idle')\n    return\n  }\n  const draftBase = resolveCommitDraftBase(options)\n  if (draftBase === null) {\n    options.setState('idle')\n    return\n  }\n\n  const draftAtStop = options.transcriptAlreadyApplied ? options.latestDraftRef.current : appendToDraft(draftBase, transcript)\n  options.latestDraftRef.current = draftAtStop\n  options.actionsRef.current.setDraft(draftAtStop)\n  // Honor the local toggle so an off switch never flashes \"polishing\".\n  // An enabled toggle still asks the Host even with an empty local pair;\n  // the Host resolves dsh's agent-default-model selection in that case.\n  if (options.isCurrent !== undefined && !options.isCurrent()) {\n    options.setState('idle')\n    return\n  }\n  if (!shouldRequestPolish(options.settings)) {\n    options.setState('idle')\n    return\n  }\n  void polishDraft({\n    transcript,\n    baseDraft: draftBase,\n    originalDraft: options.baseDraft,\n    draftAtStop,\n    provider: options.settings.polishProvider,\n    model: options.settings.polishModel,\n    reasoningEffort: options.settings.polishReasoningEffort,\n    remote: options.remote,\n    setState: options.setState,\n    latestDraftRef: options.latestDraftRef,\n    actionsRef: options.actionsRef,\n    polishAbortRef: options.polishAbortRef,\n    isCurrent: options.isCurrent\n  })\n}\n\nexport function shouldRequestPolish(settings: Pick<EarsSettings, 'polishingEnabled'>): boolean {\n  return settings.polishingEnabled\n}\n\nfunction resolveCommitDraftBase(options: CommitTranscriptOptions): string | null {\n  if (!options.requireUnchanged) return options.baseDraft\n  const expectedDraft = options.expectedDraft ?? options.baseDraft\n  const currentDraft = options.latestDraftRef.current\n  if (currentDraft === expectedDraft) return options.baseDraft\n  // Clearing the composer is an intentional reset of the old draft, not a\n  // conflicting edit. The transcript should become the new draft instead of\n  // being discarded by stale-result protection.\n  if (currentDraft.trim() === '') return ''\n  return null\n}\n\nexport interface PolishDraftOptions {\n  transcript: string\n  baseDraft: string\n  originalDraft: string\n  draftAtStop: string\n  provider: string\n  model: string\n  reasoningEffort: string\n  remote: EarsRemote\n  setState: (state: VoiceInputState, detail?: string, detailCode?: string, detailParams?: VoiceStateDetailParams) => void\n  latestDraftRef: { current: string }\n  actionsRef: { current: DraftActions }\n  polishAbortRef: { current: AbortController | null }\n  isCurrent?: () => boolean\n}\n\nexport async function polishDraft(options: PolishDraftOptions): Promise<void> {\n  if (options.isCurrent !== undefined && !options.isCurrent()) return\n  const controller = new AbortController()\n  options.polishAbortRef.current = controller\n  options.setState('polishing')\n\n  try {\n    const result = await options.remote.polish(options.transcript, options.provider, options.model, options.reasoningEffort, controller.signal)\n    if (controller.signal.aborted) return\n    if (!shouldApplyPolishResult(options.latestDraftRef.current, options.draftAtStop, options.baseDraft, options.originalDraft)) {\n      if (!controller.signal.aborted) options.setState('idle')\n      return\n    }\n\n    if (!result.ok) {\n      const detailCode = isEarsErrorCode(result.error.code) ? result.error.code : undefined\n      const detail = remoteFailureDetail(result.error)\n      if (detailCode === undefined) options.setState('polish-error', detail)\n      else options.setState('polish-error', detail, detailCode)\n      return\n    }\n    if (result.value.status === 'error') {\n      const detailCode = isEarsErrorCode(result.value.code) ? result.value.code : undefined\n      const detail = remoteFailureDetail(result.value)\n      if (detailCode === undefined) options.setState('polish-error', detail)\n      else options.setState('polish-error', detail, detailCode, result.value.params)\n      return\n    }\n    const text = result.value.text.trim() !== '' ? result.value.text.trim() : options.transcript\n    const nextDraft = appendToDraft(options.baseDraft, text)\n    options.latestDraftRef.current = nextDraft\n    options.actionsRef.current.setDraft(nextDraft)\n    options.setState('idle')\n  } catch (error) {\n    if (controller.signal.aborted) return\n    const message = failureMessage(error)\n    if (classifyVoiceFailure(message) === 'empty') {\n      options.setState('idle')\n      return\n    }\n    const code = error !== null && typeof error === 'object' && 'code' in error && typeof error.code === 'string' && isEarsErrorCode(error.code) ? error.code : undefined\n    const detail = remoteFailureDetail({ message })\n    const detailParams = remoteFailureParams(error)\n    if (code === undefined) options.setState('polish-error', detail)\n    else options.setState('polish-error', detail, code, detailParams)\n  } finally {\n    if (options.polishAbortRef.current === controller) options.polishAbortRef.current = null\n  }\n}\n\nexport function shouldApplyPolishResult(currentDraft: string, draftAtStop: string, baseDraft: string, originalDraft = baseDraft): boolean {\n  const current = collapseDraft(currentDraft)\n  const effectiveBase = collapseDraft(baseDraft)\n  const original = collapseDraft(originalDraft)\n  return current === collapseDraft(draftAtStop) || (original !== '' && effectiveBase === original && current === original)\n}\n\nfunction collapseDraft(text: string): string {\n  return text.replace(/\\s+/g, ' ').trim()\n}\n\nexport function updateDraft(\n  baseDraft: string,\n  transcript: string,\n  latestDraftRef: { current: string },\n  actionsRef: { current: DraftActions }\n): string {\n  const nextDraft = appendToDraft(baseDraft, transcript)\n  latestDraftRef.current = nextDraft\n  actionsRef.current.setDraft(nextDraft)\n  return nextDraft\n}\n\nexport function appendToDraft(baseDraft: string, transcript: string): string {\n  return joinSpacedSegments(baseDraft, transcript)\n}\n"
    },
    {
      "path": "src/index.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport { EarsSettingsSchema } from './config-schema.js'\nimport { PolishService } from './polish/service.js'\n\nexport const name = 'dsh-ears'\n\n/** Plugin configuration schema; dsh derives the entry's settings form from it. */\nexport const Config = EarsSettingsSchema\n\n/** The settings service owns the profile entry config this plugin reads and writes. */\nexport const inject = ['settings']\n\nexport async function apply(ctx: Context): Promise<void> {\n  // dsh-ears ships its own settings page, so the loader entry must not also\n  // render an automatically generated form. `configure` binds the policy to the\n  // calling fiber — the loader entry here, not the nested service below it.\n  const disposePresentation = ctx.settings.configure({ auto: false })\n  ctx.effect(() => disposePresentation, 'dsh-ears settings presentation')\n\n  await ctx.plugin(PolishService)\n\n  ctx.effect(() => {\n    return () => undefined\n  }, 'dsh-ears lifecycle')\n}\n"
    },
    {
      "path": "src/client/MicrophoneButton.tsx",
      "content": "import { useEffect, useRef } from 'react'\nimport type { SnapshotSelectorHook } from '@deepseek-ai/dsh-client-ui-slots'\nimport type { InputActions, InputState } from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport { Tooltip } from '@deepseek-ai/dsh-client-ui-primitives'\nimport { effectiveRecognitionLanguage, effectiveRecordingSeconds } from '../config.js'\nimport { isEarsErrorCode } from '../errors.js'\nimport type { EarsSettings } from '../config.js'\nimport type { AsrBackendInfo } from '../remote-contract.js'\nimport { AudioLevelMonitor } from '../asr/audio-level.js'\nimport { MediaRecorderSession, isMediaRecorderAvailable, warmMicrophone } from '../asr/media-recorder.js'\nimport { RealtimeAudioCaptureSession, isRealtimeAudioCaptureAvailable } from './realtime-audio-capture.js'\nimport { WebSpeechSession, isWebSpeechAvailable } from '../asr/web-speech.js'\nimport type { EarsRemote } from '../remote.js'\nimport styles from './MicrophoneButton.module.css'\nimport { base64ByteLength, classifyVoiceFailure, failureMessage, isTrivialRecording, remoteFailureDetail, remoteFailureParams } from './voice-error.js'\nimport { commitTranscript, updateDraft } from './voice-flow.js'\nimport { matchesShortcut } from '../shortcut.js'\nimport { fallbackTranslate, localizedErrorText, type Translate } from './settings-locale.js'\nimport { resolveCaptureBackend, isSupersededMediaCapture, reuseInFlightPromise, settleWithin, shouldAbandonPendingCapture, webSpeechCommittedTranscript } from './voice-capture.js'\nimport { micUnavailableReason, type MicUnavailableReason } from './mic-availability.js'\nimport type { BackendHook, WhisperModelHook } from './settings-controller.js'\nimport { playClick, resumeSounds, retainSounds } from './sounds.js'\nimport { createVoiceStateSetter, useVoiceInputSession, type VoiceInputSession } from './voice-session.js'\nimport { isTranscriptionStillCurrent, prepareRecordedAudioForBackend, type MediaCaptureBackend } from './local-whisper-audio.js'\nimport { isCloudAsrRealtime } from '../asr/providers.js'\n\nconst REALTIME_STOP_TIMEOUT_MS = 4_000\n\ntype VoiceInputButtonProps = {\n  readonly useInput: SnapshotSelectorHook<InputState>\n  readonly inputActions: InputActions\n  readonly remote: EarsRemote\n  readonly useEarsSettings: SnapshotSelectorHook<EarsSettings>\n  readonly useEarsBackends: BackendHook\n  readonly useEarsWhisper: WhisperModelHook\n  readonly voiceSession: VoiceInputSession\n  readonly useUiLocale?: () => string\n  readonly t?: Translate\n  readonly earsT?: Translate\n}\n\nexport function MicrophoneButton({ useInput, inputActions, remote, useEarsSettings, useEarsBackends, useEarsWhisper, voiceSession, useUiLocale, t: slotT, earsT }: VoiceInputButtonProps) {\n  const t = slotT ?? earsT ?? fallbackTranslate\n  const voiceSnapshot = useVoiceInputSession(voiceSession)\n  const state = voiceSnapshot.state\n  const setState = createVoiceStateSetter(voiceSession)\n  const speechSessionRef = useRef<WebSpeechSession | null>(null)\n  const mediaSessionRef = useRef<MediaRecorderSession | null>(null)\n  const realtimeCaptureRef = useRef<RealtimeAudioCaptureSession | null>(null)\n  const realtimeRemoteSessionIdRef = useRef<string | null>(null)\n  const realtimeStartAbortRef = useRef<AbortController | null>(null)\n  const realtimeBaseDraftRef = useRef('')\n  const realtimeDraftRef = useRef('')\n  const levelMonitorRef = useRef<AudioLevelMonitor | null>(null)\n  const mediaBaseDraftRef = useRef('')\n  const mediaStartedAtRef = useRef(0)\n  const mediaStartCancelledRef = useRef(false)\n  const mediaStartGenerationRef = useRef(0)\n  const mediaBackendRef = useRef<MediaCaptureBackend | null>(null)\n  const transcribeAbortRef = useRef<AbortController | null>(null)\n  const realtimeStopPromiseRef = useRef<{ key: string; promise: Promise<void> } | null>(null)\n  const polishAbortRef = useRef<AbortController | null>(null)\n  const recordingTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)\n  const stopRecordingRef = useRef<(() => void | Promise<void>) | null>(null)\n  const draft = useInput((value) => value.draft)\n  const actionsRef = useRef(inputActions)\n  const latestDraftRef = useRef(draft)\n  const uiLocale = useUiLocale?.() ?? 'zh'\n  const settings = useEarsSettings((value) => value)\n  const backendInfo = useEarsBackends((value) => value)\n  const whisperView = useEarsWhisper((value) => value)\n  const settingsRef = useRef(settings)\n  settingsRef.current = settings\n  const mountedRef = useRef(true)\n  const buttonRef = useRef<HTMLButtonElement | null>(null)\n  const toggleRef = useRef<(() => void) | null>(null)\n  const gateRef = useRef<MicUnavailableReason | null>(null)\n\n  useEffect(() => {\n    actionsRef.current = inputActions\n  }, [inputActions])\n\n  useEffect(() => {\n    latestDraftRef.current = draft\n  }, [draft])\n\n  useEffect(() => {\n    // The hotkey runs on window CAPTURE so it outranks text input: editor\n    // keydown handlers (which bubble and may stopPropagation/preventDefault)\n    // never see a matched combination, so pressing the shortcut inside the\n    // composer cannot be swallowed by the input layer. When the chord does not\n    // match (or the shortcut is disabled/gated), the event is left untouched.\n    const onKeyDown = (event: KeyboardEvent) => {\n      const current = settingsRef.current\n      if (current.voiceShortcutEnabled === false) return\n      if (event.isComposing || event.repeat) return\n      if (!matchesShortcut(current.voiceShortcut, event)) return\n      const target = event.target\n      if (target instanceof Element && target.closest('[role=\"dialog\"]') !== null) return\n      if (document.visibilityState !== 'visible') return\n      const element = buttonRef.current\n      if (element === null || element.offsetParent === null) return\n      event.preventDefault()\n      event.stopPropagation()\n      if (gateRef.current !== null) {\n        if (document.activeElement !== element) element.focus()\n        return\n      }\n      toggleRef.current?.()\n    }\n    window.addEventListener('keydown', onKeyDown, true)\n    return () => window.removeEventListener('keydown', onKeyDown, true)\n  }, [])\n\n  useEffect(() => {\n    stopRecordingRef.current = null\n    const stop = voiceSession.onStopRequested(() => {\n      void stopRecordingRef.current?.()\n    })\n    const cancel = voiceSession.onCancelRequested(() => {\n      transcribeAbortRef.current?.abort()\n      polishAbortRef.current?.abort()\n      mediaStartCancelledRef.current = true\n      realtimeStartAbortRef.current?.abort()\n      realtimeStartAbortRef.current = null\n      const realtimeCapture = realtimeCaptureRef.current\n      realtimeCaptureRef.current = null\n      realtimeCapture?.abort()\n      const sessionId = realtimeRemoteSessionIdRef.current\n      realtimeRemoteSessionIdRef.current = null\n      if (sessionId !== null) void remote.cancelRealtime(sessionId)\n    })\n    return () => {\n      stop()\n      cancel()\n    }\n  }, [voiceSession])\n\n  useEffect(() => {\n    mountedRef.current = true\n    const releaseSounds = retainSounds()\n    return () => {\n      mountedRef.current = false\n      stopRecordingRef.current = null\n      voiceSession.setState('idle')\n      levelMonitorRef.current?.stop()\n      levelMonitorRef.current = null\n      speechSessionRef.current?.abort()\n      speechSessionRef.current = null\n      mediaSessionRef.current?.abort()\n      mediaSessionRef.current = null\n      realtimeStartAbortRef.current?.abort()\n      realtimeStartAbortRef.current = null\n      realtimeCaptureRef.current?.abort()\n      realtimeCaptureRef.current = null\n      const realtimeSessionId = realtimeRemoteSessionIdRef.current\n      realtimeRemoteSessionIdRef.current = null\n      if (realtimeSessionId !== null) void remote.cancelRealtime(realtimeSessionId)\n      mediaBackendRef.current = null\n      transcribeAbortRef.current?.abort()\n      polishAbortRef.current?.abort()\n      clearRecordingTimer(recordingTimerRef)\n      releaseSounds()\n    }\n  }, [voiceSession])\n\n  const active = state === 'starting' || state === 'recording'\n  const busy = state === 'transcribing' || state === 'polishing'\n  const backend = resolveCaptureBackend(settings.asrBackend)\n  const configUnavailable = !active && !busy && backend !== null && (state === 'idle' || state === 'error' || state === 'polish-error' || state === 'upstream-error')\n    ? micUnavailableReason(backend, backendInfo, whisperView)\n    : null\n  gateRef.current = backend === null ? { kind: 'backend', backendId: 'web-speech' } : configUnavailable\n\n  if (!active && !busy && backend === null) {\n    return (\n      <Tooltip label={t('voiceUnavailable')} side=\"top\" delayMs={200} portal>\n        <button\n          ref={buttonRef}\n          type=\"button\"\n          aria-label={t('voiceUnavailable')}\n          aria-disabled=\"true\"\n          className={styles.button}\n        >\n          <MicrophoneIcon />\n        </button>\n      </Tooltip>\n    )\n  }\n\n  if (!active && !busy && configUnavailable !== null) {\n    return (\n      <Tooltip label={micUnavailableTooltip(configUnavailable, backendInfo.backends, t)} side=\"top\" delayMs={200} portal>\n        <button\n          ref={buttonRef}\n          type=\"button\"\n          aria-label={t('voiceUnavailable')}\n          aria-disabled=\"true\"\n          className={styles.button}\n        >\n          <MicrophoneIcon />\n        </button>\n      </Tooltip>\n    )\n  }\n\n  let backendAvailable: boolean\n  if (backend === 'web-speech') {\n    backendAvailable = isWebSpeechAvailable()\n  } else if (backend === 'cloud-openai' && isCloudAsrRealtime(settings)) {\n    backendAvailable = isRealtimeAudioCaptureAvailable()\n  } else {\n    backendAvailable = isMediaRecorderAvailable()\n  }\n  if (!active && !busy && !backendAvailable) {\n    const unavailableLabel = backend === 'web-speech' ? t('voiceUnavailableWebSpeech') : t('voiceUnavailableRecorder')\n    return (\n      <Tooltip label={unavailableLabel} side=\"top\" delayMs={200} portal>\n        <button\n          ref={buttonRef}\n          type=\"button\"\n          aria-label={t('voiceUnavailable')}\n          aria-disabled=\"true\"\n          className={styles.button}\n        >\n          <MicrophoneIcon />\n        </button>\n      </Tooltip>\n    )\n  }\n\n  const startWebSpeech = () => {\n    let baseDraft = draft\n    // Supersede any pending media capture before starting Web Speech.\n    mediaStartGenerationRef.current += 1\n    let sessionDraft = baseDraft\n    let failed = false\n    mediaStartCancelledRef.current = false\n    setState('starting')\n\n    let session!: WebSpeechSession\n    let levelMonitorStarting = false\n    const startLevelMonitor = () => {\n      if (levelMonitorStarting || levelMonitorRef.current !== null) return\n      levelMonitorStarting = true\n      void AudioLevelMonitor.capture((level) => voiceSession.pushAudioLevel(level)).then((monitor) => {\n        levelMonitorStarting = false\n        if (!mountedRef.current || speechSessionRef.current !== session) {\n          monitor.stop()\n          return\n        }\n        levelMonitorRef.current?.stop()\n        levelMonitorRef.current = monitor\n      }).catch(() => {\n        levelMonitorStarting = false\n        // Web Speech remains usable when the optional waveform analyser is unavailable.\n      })\n    }\n\n    const updateLiveDraft = (text: string) => {\n      const currentDraft = latestDraftRef.current\n      if (currentDraft !== sessionDraft) {\n        if (currentDraft.trim() !== '') return\n        // Treat clearing the composer as the new insertion point for this\n        // recognition session rather than restoring the old draft.\n        baseDraft = ''\n      }\n      sessionDraft = updateDraft(baseDraft, text, latestDraftRef, actionsRef)\n    }\n\n    try {\n      session = new WebSpeechSession({\n        language: effectiveRecognitionLanguage(settingsRef.current.webSpeechLanguage, uiLocale),\n        onStart: () => {\n          startLevelMonitor()\n        },\n        onInterim: updateLiveDraft,\n        onFinal: updateLiveDraft,\n        onError: (error) => {\n          failed = true\n          levelMonitorRef.current?.stop()\n          levelMonitorRef.current = null\n          applyVoiceFailure(voiceSession, 'asr', error)\n        },\n        onEnd: (text) => {\n          clearRecordingTimer(recordingTimerRef)\n          levelMonitorRef.current?.stop()\n          levelMonitorRef.current = null\n          speechSessionRef.current = null\n          const transcript = webSpeechCommittedTranscript({ sessionText: text, sessionDraft, baseDraft })\n          if (failed || transcript === '') {\n            if (!failed) setState('idle')\n            return\n          }\n          const epoch = voiceSession.captureEpoch()\n          commitTranscript({\n            transcript,\n            baseDraft,\n            expectedDraft: sessionDraft,\n            requireUnchanged: true,\n            settings: settingsRef.current,\n            remote,\n            setState,\n            latestDraftRef,\n            actionsRef,\n            polishAbortRef,\n            isCurrent: () => voiceSession.isCurrentEpoch(epoch)\n          })\n        }\n      })\n\n      speechSessionRef.current = session\n      session.start()\n      setState('recording')\n      armRecordingTimer(recordingTimerRef, settingsRef.current.maxRecordingSeconds, () => session.stop())\n    } catch {\n      levelMonitorRef.current?.stop()\n      levelMonitorRef.current = null\n      speechSessionRef.current = null\n      if (mountedRef.current) applyVoiceFailure(voiceSession, 'asr', new Error('Speech recognition is unavailable in this browser'))\n    }\n  }\n\n  const stopRealtimeRecording = () => {\n    const capture = realtimeCaptureRef.current\n    const sessionId = realtimeRemoteSessionIdRef.current\n    if (capture === null || sess